            <div>
                <h1 className="font-extrabold text-5xl text-red-500 mt-10 text-center">DIGITAL</h1>
                <p className="underline text-xl pl-5" >Go Back</p>
                <div className="flex flex-row pt-10">

                    <div className="flex flex-col">
